import json
import sys

# Actions treated here as not scopable to one resource (ECR login, task definition registration).
UNSCOPED_OK = {"ecr:GetAuthorizationToken", "ecs:RegisterTaskDefinition",
               "ecs:DescribeTaskDefinition"}


def as_list(value):
    return [value] if isinstance(value, str) else value


def check(path):
    doc = json.load(open(path))
    problems = []
    if doc.get("Version") != "2012-10-17":
        problems.append("Version is not 2012-10-17")
    statements = doc["Statement"]
    if isinstance(statements, dict):
        statements = [statements]
    for i, st in enumerate(statements):
        sid = st.get("Sid", "#%d" % i)
        actions = as_list(st.get("Action", []))
        resources = as_list(st.get("Resource", []))
        if st.get("Effect") not in ("Allow", "Deny"):
            problems.append("%s: Effect must be Allow or Deny" % sid)
        if any(a == "*" or a.endswith(":*") for a in actions):
            problems.append("%s: wildcard action in %s" % (sid, actions))
        if "*" in resources and not set(actions) <= UNSCOPED_OK:
            problems.append("%s: Resource * used with %s" % (sid, actions))
    print("%s: %d problem(s)" % (path, len(problems)))
    for p in problems:
        print("  - " + p)


for name in sys.argv[1:]:
    check(name)

