{
  "family": "orders-service",
  "requiresCompatibilities": ["FARGATE"],
  "networkMode": "awsvpc",
  "cpu": "512",
  "memory": "1024",
  "executionRoleArn": "arn:aws:iam::123456789012:role/orders-task-execution-role",
  "taskRoleArn": "arn:aws:iam::123456789012:role/orders-task-role",
  "containerDefinitions": [
    {
      "name": "orders-service",
      "image": "123456789012.dkr.ecr.ap-south-1.amazonaws.com/orders-service:1.4.0",
      "essential": true,
      "portMappings": [{"containerPort": 8080, "protocol": "tcp"}],
      "environment": [
        {"name": "SPRING_DATASOURCE_URL",
         "value": "jdbc:postgresql://orders-db.abc123.ap-south-1.rds.amazonaws.com:5432/orders"},
        {"name": "SPRING_DATASOURCE_USERNAME", "value": "orders_app"},
        {"name": "JAVA_TOOL_OPTIONS", "value": "-XX:MaxRAMPercentage=75"}
      ],
      "secrets": [
        {"name": "SPRING_DATASOURCE_PASSWORD",
         "valueFrom":
           "arn:aws:secretsmanager:ap-south-1:123456789012:secret:orders/db-a1b2c3:password::"}
      ],
      "logConfiguration": {
        "logDriver": "awslogs",
        "options": {
          "awslogs-group": "/ecs/orders-service",
          "awslogs-region": "ap-south-1",
          "awslogs-stream-prefix": "orders"
        }
      }
    }
  ]
}

provider "aws" {
  region = "ap-south-1"
}

